import React from 'react';
import { LIN_ERP_LIST_FILTER_LAYOUT } from '@linm-soft-org/linm-web-common-components';
import styles from './ErpFilterCardHeader.module.css';

interface Props {
  title: string;
  testIdPrefix: string;
  children: React.ReactNode;
}

/** TableCard header — title trái · filter cụm phải (package wrap SSOT). */
export const ErpFilterCardHeader: React.FC<Props> = ({ title, testIdPrefix, children }) => (
  <div className={styles.root} data-lin-table-card-header="">
    <div className={LIN_ERP_LIST_FILTER_LAYOUT.header}>
      <div className={`tableTitleBlock ${styles.tableTitleBlock}`}>
        <span className={`tableTitle ${styles.tableTitle}`}>{title}</span>
      </div>
      <div
        className={LIN_ERP_LIST_FILTER_LAYOUT.filtersHost}
        data-testid={`${testIdPrefix}-filters`}
      >
        {children}
      </div>
    </div>
  </div>
);
